  document.title = `${item.title} — Чешуя`;
  document.querySelector('.zine-info h1').textContent = item.title;
  document.querySelector('.zine-meta').textContent = `Выставка · ${item.year}`;
  const detail = details[item.id];
  const place = document.querySelector('.exhibition-place');
  const copy = document.createElement('div');
  copy.className = 'exhibition-copy';
  place.after(copy);
  const renderCopy = locale => {
    document.querySelector(".zine-meta").textContent = `${locale === "en" ? "Exhibition" : "Выставка"} · ${item.year}`;
    const translated = detail?.[locale === 'en' ? 'en' : 'ru'];
    place.textContent = translated?.place || item.description;
    copy.replaceChildren(...(translated?.paragraphs || []).map(text => {
      const paragraph = document.createElement('p');
      paragraph.textContent = text;
      return paragraph;
    }));
    const videoHeading = document.querySelector('.exhibition-video h2');
    if (videoHeading) videoHeading.textContent = locale === 'en' ? 'Video' : 'Видео';
  };
  if (detail?.videoId) {
    const section = document.createElement('section');
    section.className = `exhibition-video${detail.shortVideo ? ' is-short' : ''}`;
    section.setAttribute('aria-label', 'Видео выставки');
    const heading = document.createElement('h2');
    const frame = document.createElement('div');
    frame.className = 'exhibition-video-frame';
    const iframe = document.createElement('iframe');
    iframe.src = `https://www.youtube-nocookie.com/embed/${detail.videoId}`;
    iframe.title = `${item.title} — видео`;
    iframe.loading = 'lazy';
    iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
    iframe.referrerPolicy = 'strict-origin-when-cross-origin';
    iframe.allowFullscreen = true;
    frame.append(iframe);
    section.append(heading, frame);
    document.querySelector('.exhibition-page').append(section);
  }
  document.addEventListener('cheshuya:locale', event => renderCopy(event.detail));
